1→"""Count words and lines from standard input, with an optional frequency ranking."""

from __future__ import annotations

import re
import sys
from collections import Counter

USAGE = (
10→    "Usage: textstats [--top N]  # read stdin, print word and line counts; "
    "with --top N also print the N most frequent words\n"
)

_TOP_N = re.compile(r"[1-9][0-9]*")


def count_words(text: str) -> int:
    return len(text.split())

20→
def count_lines(text: str) -> int:
    if text == "":
        return 0
    return text.count("\n") + (0 if text.endswith("\n") else 1)


def main(argv: list[str] | None = None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    if args == ["--help"]:
30→        sys.stdout.write(USAGE)
        return 0
    top_n: int | None = None
    if args:
        if len(args) != 2 or args[0] != "--top" or _TOP_N.fullmatch(args[1]) is None:
            sys.stderr.write(USAGE)
            return 2
        top_n = int(args[1])
    data = sys.stdin.read()
    sys.stdout.write(f"words: {count_words(data)}\nlines: {count_lines(data)}\n")
40→    if top_n is not None:
        counts = Counter(data.split())
        ranked = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
        for word, freq in ranked[:top_n]:
            sys.stdout.write(f"{word} {freq}\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
